import bpy,json,hashlib
from pathlib import Path
w=Path('/workspace/monroe-pavement-fix');d=w/'delivery';variants={}
def active(o):return o.type=='MESH' and not any(o.get(k) for k in ['_proposal_backup','_screenshot_backup','_variant_backup','_material_backup','_townhouse_backup'])
for variant,folder,name in [('existing','01_Original_Road_Layout','Monroe_Original_Road_Layout'),('proposed','02_New_Road_Layout','Monroe_New_Road_Layout')]:
 bpy.ops.wm.open_mainfile(filepath=str(d/folder/(name+'.blend')));objects={};evidence=[]
 for o in bpy.context.scene.objects:
  if not active(o) or not o.name.startswith('building_'):continue
  data={'points':[list(o.matrix_world@v.co) for v in o.data.vertices],'faces':[list(f.vertices) for f in o.data.polygons]};geo=hashlib.sha256(json.dumps(data,separators=(',',':')).encode()).hexdigest();mat=o.data.materials[0];appearance={'diffuse':list(mat.diffuse_color),'textures':sorted(hashlib.sha256(bytes(n.image.packed_file.data)).hexdigest() for n in mat.node_tree.nodes if n.type=='TEX_IMAGE' and n.image and n.image.packed_file),'uv':[list(v.uv) for v in o.data.uv_layers.active.data] if o.data.uv_layers.active else []};appearance=hashlib.sha256(json.dumps(appearance,separators=(',',':')).encode()).hexdigest();objects[o.name]={'geometry':geo,'appearance':appearance};evidence.append({'building':o.name,'material':mat.name,'facade_evidence_status':o.get('facade_evidence_status','Earlier source interpretation, not fully verified.'),'roof_evidence_status':o.get('roof_reference_status','Retained prior roof appearance.')})
 variants[variant]=objects;(d/'validation'/(variant+'_facade_evidence.json')).write_text(json.dumps(evidence,indent=2))
a,b=variants['existing'],variants['proposed'];missing=sorted(set(a)^set(b));geometry=[n for n in set(a)&set(b) if a[n]['geometry']!=b[n]['geometry']];appearance=[n for n in set(a)&set(b) if a[n]['appearance']!=b[n]['appearance']];report={'passed':not missing and not geometry and not appearance and len(a)==3155,'building_count_each_option':len(a),'missing_between_options':missing,'geometry_differences':geometry,'appearance_differences':appearance,'apartment_and_school_identical':all(n in a and n in b and a[n]==b[n] for n in ['building_2603','building_2356','building_2099','building_2772']),'comparison_scope':'Exact world vertices/faces and material/texture/UV signatures. Only site circulation differs.'};(d/'validation/shared_buildings_between_options.json').write_text(json.dumps(report,indent=2));print('SHARED_BUILDINGS',report,flush=True);assert report['passed'],report
